import{z as s,x as n,o as E,c as i,q as A,j as o,D as e,d as r,s as m,S as t}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"张量核的编程直觉","description":"","frontmatter":{"title":"张量核的编程直觉","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-tensorcore-programming.md","filePath":"cs/gpu-tensorcore-programming.md","lastUpdated":1791413859000}'),B={name:"cs/gpu-tensorcore-programming.md"};function p(d,a,c,C,F,g){const l=n("Mermaid");return E(),i("div",null,[a[2]||(a[2]=A('<h1 id="张量核的编程直觉" tabindex="-1">张量核的编程直觉 <a class="header-anchor" href="#张量核的编程直觉" aria-label="Permalink to &quot;张量核的编程直觉&quot;">​</a></h1><div class="epigraph"><p>张量核不是更快的加法器，而是一纸布局合同：数据按碎片摆进寄存器，阵列才动——摆不对，312 TFLOPS 与你无关。</p><footer>—— 据 NVIDIA PTX ISA 的 mma 指令文档与 A100/Hopper 架构白皮书整理</footer></div><p><a href="/cs/gpu-smem-bank-conflicts">上一课</a>把块级交换的账算清；本课进入专用矩阵单元。大模型栏已从两个高度看过它：<a href="/llm/tensor-core">Tensor Core</a> 给了它在模型里的角色，<a href="/llm/wgmma">WGMMA / wgmma 指令</a>给了 Hopper 的指令合同，<a href="/llm/cublas-cudnn">cuBLAS / cuDNN 边界</a>划了库的管辖。本课补最底一层的编程直觉：fragment 怎么持有、指令怎么挑、吞吐从哪来、又从哪三个口漏掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FP32 CUDA core 的吞吐有硬顶：A100 全卡约 19.5 TFLOPS，而训练与推理的主算子是矩阵乘，靠通用 FMA 流水喂不出这个量。Volta 起每个 SM 配专用 MAC 阵列，fp16 稠密峰值 312 TFLOPS——16 倍的差。对程序员，新问题是抽象层级的膨胀：从 cuBLAS 到 <code>wmma</code> API 到 <code>mma.sync</code> PTX 到 wgmma，四层各控制什么、各自的布局合同多硬。直觉不过关的症状很典型：调了 tile 尺寸没效果、手写 MMA 结果错位、半精度核跑出个位数利用率。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自底向上过三层合同。<code>wmma</code> API 以 16×16×16 的 fragment 为单位，编译器管布局，入门够用、控制粗；<code>mma.sync</code> PTX 是手写内核的主力，fp16 常用形状 m16n8k16：A 碎片 \\(16\\times16\\) 共 256 个元素摊到 32 个 lane，每 lane 持 8 个半精度；B 是 \\(16\\times 8\\)，每 lane 4 个；累加器 \\(16\\times 8\\) 的 fp32，每 lane 4 个——lane 到元素的映射是指令文档钉死的合同，不是实现细节。wgmma 在 Hopper 上以 4-warp 的 warpgroup 为单元、操作数可直接取自 smem、完成靠 commit/wait 组，<a href="/llm/wgmma">wgmma 课</a>已给过配对纪律，本课不重复。数据流模板在三代硬件上同构：global 合并读入 smem（swizzle 对齐碎片），smem 装载成 fragment，MMA 原地累加，epilogue 写回。</p>',7)),(E(),o(t,null,{default:e(()=>[m(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22global%EF%BC%9A%E5%90%88%E5%B9%B6%E8%AF%BB%E5%85%A5%22%5D%20--%3E%20SM%5B%22smem%EF%BC%9Aswizzle%20%E5%AF%B9%E9%BD%90%E7%A2%8E%E7%89%87%E5%B8%83%E5%B1%80%22%5D%0A%20%20SM%20--%3E%20FR%5B%22fragment%EF%BC%9A%E6%AF%8F%20lane%20%E6%8C%89%E5%90%88%E5%90%8C%E6%8C%81%208%2F4%2F4%20%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%0A%20%20FR%20--%3E%20MMA%5B%22MMA%20%E5%8E%9F%E5%9C%B0%E7%B4%AF%E5%8A%A0%EF%BC%8Cfp32%20%E7%B4%AF%E5%8A%A0%E5%99%A8%22%5D%0A%20%20MMA%20--%3E%7C%E4%B8%8B%E4%B8%80%20k%20%E5%9D%97%7C%20FR%0A%20%20MMA%20--%3E%20EPI%5B%22epilogue%EF%BC%9A%E5%86%99%E5%9B%9E%20global%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>吞吐的来源是专用化，不是频率：一个 tensor core 每拍做 256 组 fp16 FMA（512 FLOP），A100 每 SM 四个，全卡 108 个 SM 合出 312 TFLOPS。<span class="marginnote">数字实例：峰值表就是把三笔乘出来的——\\(4\\) 个核 \\(\\times\\) 每核每拍 \\(512\\) FLOP \\(\\times\\) 锁频 \\(1.41\\) GHz \\(\\approx 2.9\\) TFLOPS 单 SM，再乘 \\(108\\) 个 SM 得约 \\(312\\) TFLOPS。哪天你在别的卡上看到不同峰值，先拆这三笔，别背表。</span>代价是数据必须按阵列要的形状就位——MMA 阵列深流水，k 方向的料断一拍，整条阵列空转一拍，所以「喂料」与「计算」必须重叠：smem 到 fragment 的搬运用双缓冲藏在上一块的 MMA 后面（<a href="/llm/sw-pipeline-buffer">软件流水课</a>的 stage 账在这里兑现）。<span class="marginnote">直觉类比：MMA 阵列是一条传送带流水线，k 方向每来一块料就整体加工一次；料断一拍，整条传送带空转一拍，这一拍就是 \\(512\\times4\\times108\\) FLOP 凭空蒸发。双缓冲的用途就是让「搬下一块料」发生在「算手头这块」的影子里，传送带不断供。</span>上一课的 swizzle 在这里回到正位：smem 布局要同时满足写侧的合并与读侧的碎片对齐，padding 换行宽的路数在 MMA 布局下走不通，只能 swizzle。</p><p>漏吞吐的三个口要背下来。形状口：M、N、K 不是 tile 尺寸的倍数时，padding 的算力白烧，边缘 tile 占比在小矩阵上能到一半。喂料口：k 复用不足（tile 太扁）时 MMA 等数，张量核利用率低而访存墙远没到——症状是 stall 在 wait 而非 long scoreboard，profiling 课会给证据。规模口：decode 的小 batch 使 \\(M\\) 只有几行，阵列大部分 lane 无事可做——<a href="/llm/wgmma">wgmma 课</a>的结论「峰值表不能当 decode SLA」就是这一口的极端情形。</p>',3)),(E(),o(t,null,{default:e(()=>[m(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E5%BC%A0%E9%87%8F%E6%A0%B8%E5%88%A9%E7%94%A8%E7%8E%87%E4%BD%8E%22%5D%20--%3E%20SHAPE%7B%22%E5%BD%A2%E7%8A%B6%E5%8F%A3%EF%BC%9AM%2FN%2FK%20%E6%98%AF%20tile%20%E5%B0%BA%E5%AF%B8%E7%9A%84%E5%80%8D%E6%95%B0%EF%BC%9F%22%7D%0A%20%20SHAPE%20--%3E%7C%22%E5%90%A6%22%7C%20PAD%5B%22padding%20%E7%99%BD%E7%83%A7%EF%BC%8C%E8%BE%B9%E7%BC%98%20tile%20%E5%8D%A0%E6%AF%94%E9%AB%98%22%5D%0A%20%20SHAPE%20--%3E%7C%22%E6%98%AF%22%7C%20FEED%7B%22%E5%96%82%E6%96%99%E5%8F%A3%EF%BC%9Astall%20%E5%81%9C%E5%9C%A8%E5%93%AA%EF%BC%9F%22%7D%0A%20%20FEED%20--%3E%7C%22wait%EF%BC%9Ak%20%E5%A4%8D%E7%94%A8%E4%B8%8D%E8%B6%B3%22%7C%20TILE%5B%22tile%20%E5%A4%AA%E6%89%81%EF%BC%8CMMA%20%E7%AD%89%E6%95%B0%22%5D%0A%20%20FEED%20--%3E%7C%22long%20scoreboard%22%7C%20MEM%5B%22%E5%85%88%E4%BF%AE%E8%AE%BF%E5%AD%98%E4%B8%8E%E5%90%88%E5%B9%B6%22%5D%0A%20%20FEED%20--%3E%7C%22%E9%83%BD%E4%B8%8D%E6%98%AF%22%7C%20SCALE%7B%22%E8%A7%84%E6%A8%A1%E5%8F%A3%EF%BC%9AM%20%E5%8F%AA%E6%9C%89%E5%87%A0%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20SCALE%20--%3E%7C%22%E6%98%AF%22%7C%20DECODE%5B%22%E5%B0%8F%20batch%EF%BC%8C%E9%98%B5%E5%88%97%E5%A4%A7%E9%9D%A2%E7%A7%AF%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20SCALE%20--%3E%7C%22%E5%90%A6%22%7C%20BACK%5B%22%E5%9B%9E%E5%88%B0%20NCU%20%E5%AF%B9%E8%B4%A6%EF%BC%8C%E6%8D%A2%E5%81%87%E8%AE%BE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>数值格式（fp16/bf16/fp8 的舍入与累加精度）是低精度数值的题目，本课只记一条：累加器是 fp32，别在 epilogue 之前降精度。<span class="marginnote">常见误区：「fp16 输入就是全程半精度」。实际上乘法结果在 fp32 累加器里逐次累加，几百个 k 步的舍入误差才压得住；若为省寄存器把中间累加值写回 fp16，误差一路滚，最后就是「结果大体对、收敛悄悄变差」——最难归因的那种退化。</span>反向传播与训练内核只借本课的布局直觉，不展开。整数与稀疏 MMA 各有自己的形状与合同，不进本课。CUTLASS 如何把 fragment、拷贝、MMA 组织成可复用的层——那是下一课的事；本课给的底线是：无论库包装多厚，布局合同最终都落在这三层抽象上。</p><p><span class="marginnote">手写 MMA 的第一张草稿不该是代码，是 lane 映射表：m16n8k16 里每 lane 持 A 的 8 个、B 的 4 个、C 的 4 个元素，位置由文档的行列分组钉死。凭直觉写索引几乎必然错位，而且错位的结果往往是「数值大体对、个别行互换」——最难查的那种错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>张量核把吞吐从 19.5 提到 312 TFLOPS 的代价，是数据必须按碎片布局合同就位。</li><li>三层抽象：<code>wmma</code> 管布局最省心、<code>mma.sync</code> 是手写主力、wgmma 直取 smem 并以 commit/wait 管理。</li><li>m16n8k16 的 lane 映射（8/4/4）是合同：先画表再写索引。</li><li>吞吐从三个口漏：形状不对齐、喂料不足、小 \\(M\\) 打不满阵列。</li><li>喂料与计算重叠靠双缓冲与 swizzle，衔接上一课的 bank 账。</li><li>出处：NVIDIA PTX ISA 的 <code>mma.sync</code> / <code>wgmma.mma_async</code> 文档；A100 与 Hopper 架构白皮书。</li></ul>',5))])}const D=s(B,[["render",p]]);export{M as __pageData,D as default};
